const item = $input.first().json || {};
const headers = item.headers || {};
const got = String(headers['x-internal-secret'] || headers['X-Internal-Secret'] || '').trim();
const expected = String($env.INTERNAL_WEBHOOK_SECRET || '').trim();
if (!expected || got !== expected) {
  throw new Error('Unauthorized');
}
const body = item.body && typeof item.body === 'object' ? item.body : item;
const system = String(body.system || '').trim();
const user = String(body.user || '').trim();
if (!system || !user) {
  throw new Error('system and user are required');
}
return [{ json: { openrouterMessages: [
  { role: 'system', content: system },
  { role: 'user', content: user },
] } }];

const REQUIRED = ['title', 'subject', 'location', 'summary', 'bullet_points', 'participants', 'tags'];
function messageText(message) {
  if (!message) return '';
  const content = message.content;
  if (typeof content === 'string') return content.trim();
  if (Array.isArray(content)) {
    return content.map((part) => {
      if (typeof part === 'string') return part;
      if (part && typeof part.text === 'string') return part.text;
      return '';
    }).join('').trim();
  }
  return '';
}
function parseEdited(text) {
  let source = String(text || '').trim();
  if (!source) return null;
  const fenced = source.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced) source = fenced[1].trim();
  const tryParse = (value) => {
    try { return JSON.parse(value); } catch (e) { return null; }
  };
  let parsed = tryParse(source);
  if (!parsed) {
    const start = source.indexOf('{');
    const end = source.lastIndexOf('}');
    if (start >= 0 && end > start) parsed = tryParse(source.slice(start, end + 1));
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
  if (REQUIRED.some((key) => !Object.prototype.hasOwnProperty.call(parsed, key))) return null;
  return parsed;
}
const item = $input.first().json || {};
if (item.error) {
  return [{ json: { ok: false, error: (item.error.message || item.error.description || 'NVIDIA Nemotron request failed') } }];
}
const choice = item.choices && item.choices[0];
